syntax:
```cpp
#include <locale>
#include <iostream>

int main() {
  std::locale currentLocale = std::locale(); // Get current locale
  std::cout << "Current locale: " << currentLocale.name() << std::endl;

  std::locale newLocale("en_US.UTF-8"); // Or any other valid locale
  std::locale previousLocale = std::setlocale(LC_ALL, newLocale.name().c_str());
  //LC_ALL affects all locale categories.  Consider LC_NUMERIC, LC_TIME, etc. for more granular control.
  std::cout << "New locale: " << std::locale().name() << std::endl; 
  std::cout << "Previous locale: " << previousLocale.name() << std::endl;

  // Restore the previous locale (good practice)
  std::setlocale(LC_ALL, previousLocale.name().c_str());
  return 0;
}
```

code_example:
#include <iostream>
#include <locale>
int main() {
  std::locale loc = std::locale("de_DE.UTF-8");
  std::locale prev = std::setlocale(LC_ALL, loc.name().c_str());
  std::cout << std::setprecision(3) << 3.14159 << std::endl; // Decimal separator depends on locale
  std::setlocale(LC_ALL, prev.name().c_str()); // Restore previous locale
  return 0;
}
